/*
 * A287309  Primes that can be generated by the concatenation in base 7, in
 *          descending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287309
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 31, u32 n <= 39, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   base7_digits, is_prime_big, pow_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Algorithm:  a(n) is the n-th prime that can be obtained by concatenating the base‑7 representations of two consecutive integers in descending order
 * (i+1 first, then i), interpreting the concatenated string as a base‑7 number and converting it to decimal. */

#include "../utils/pow_seq.h"
#include "../utils/is_prime_big.h"
#include "../utils/base7_digits.h"

seq_t a(idx_t n)
{
    idx_t found = 0;
    for (idx_t i = 0; ; ++i)
    {
        idx_t len   = base7_digits(i);                     /* number of base‑7 digits of i */
        seq_t power = pow_seq((seq_t)7, len);               /* 7^len */
        seq_t v     = ((seq_t)(i + 1)) * power + (seq_t)i; /* concatenated value in decimal */

        if (is_prime_big(v))
        {
            ++found;
            if (found == n)
                return v;
        }
    }
}
